def test_command_ids_are_unique_and_every_row_has_an_icon():
    ids = [command.id for command in COMMANDS]
    assert len(ids) == len(set(ids))
    assert all(command.icon and command.group and command.title for command in COMMANDS)


def test_every_command_runs_something_real():
    for command in COMMANDS:
        if command.event:
            assert hasattr(State, command.event[0]), command.id
        if command.shown:
            assert command.shown in State.get_fields() or hasattr(State, command.shown), command.id
        palette_row(command)  # builds: the event takes these arguments


def test_a_pressed_command_is_a_shortcut_the_browser_knows():
    """window.smashPress runs it as a key press, so panes.js must know the key"""
    pressed = [command.press for command in COMMANDS if command.press]
    assert pressed
    assert set(pressed) <= set(BROWSER_SHORTCUTS)
    assert set(RUNNABLE) <= set(BROWSER_SHORTCUTS)
    assert Shortcut.CLOSE not in RUNNABLE  # Enter on Escape would only close the list


def test_the_palette_has_what_the_plus_menu_adds_and_the_pane_toggles():
    ids = {command.id for command in COMMANDS}
    assert {f"add.{widget.kind}" for widget in ADDABLE} <= ids
    assert {"view.chat", "view.results", "view.python", "app.keys"} <= ids
    python = next(command for command in COMMANDS if command.id == "view.python")
    assert (python.shown, python.keys) == ("show_python", Shortcut.TOGGLE_PYTHON.keys)


def test_a_command_needs_exactly_one_way_to_run():
    with pytest.raises(ValueError, match="exactly one"):
        Command("x", "App", "X", "i")
    with pytest.raises(ValueError, match="exactly one"):
        Command("x", "App", "X", "i", event=("toggle_help",), press=Shortcut.KEYS)


# -- slash commands ---------------------------------------------------------------


@pytest.fixture(autouse=True)
def _no_session_left_behind():
    """A State made here has the empty client token; its session must not outlive the test
    (other tests take that token as unknown).
    """
    yield
    session._SESSIONS.pop("", None)


def state(**fields: object) -> State:
    made = State(_reflex_internal_init=True)  # a flag, not a password
    for name, value in fields.items():
        setattr(made, name, value)
    return made


def submit(made: State, text: str) -> object:
    return State.submit_chat.fn(made, {"prompt": text})


def test_slash_commands_are_palette_commands_with_a_name():
    assert {"clear-chat", "clear-variables"} <= set(SLASH)
    assert all(command in COMMANDS and command.slash == name for name, command in SLASH.items())
    slash_menu()  # builds
    with pytest.raises(ValueError, match="lower-case words"):
        Command("x", "App", "X", "i", event=("toggle_help",), slash="Clear Chat")


def test_the_clear_commands_are_listed_first():
    assert list(SLASH)[:2] == ["clear-chat", "clear-variables"]
    assert len(SLASH) == sum(bool(command.slash) for command in COMMANDS)


def test_a_message_is_a_slash_command_only_when_it_starts_with_a_slash():
    assert parse_slash("what is 1/2 of 10%?") is None
    assert parse_slash("/clear-chat") == ("clear-chat", "")
    assert parse_slash("/Clear-Chat  now please ") == ("clear-chat", "now please")


def ran(events: object) -> list[tuple[str, list[str]]]:
    """What submit_chat returned, as (handler, its arguments) in the order they run."""
    found = []
    for item in events or []:
        handler = getattr(item, "handler", item)
        arguments = [json.loads(str(value)) for _, value in getattr(item, "args", ())]
        found.append((handler.fn.__name__, arguments))
    return found


def test_a_slash_command_runs_what_its_palette_row_runs_and_shows_in_the_chat():
    made = state()
    made._session().namespace["n"] = 1
    events = ran(submit(made, "/clear-variables"))
    # its row in the chat first (as a tool call's), then the palette command's own event
    assert events == [("slash_ran", ["/clear-variables", "cleared 1 variable"]), ("clear_all_vars", [])]
    State.slash_ran.fn(made, "/clear-variables", "cleared 1 variable")
    assert [(item.kind, item.name, item.text) for item in made.chat] == [
        ("slash", "/clear-variables", "cleared 1 variable")
    ]


def test_clearing_the_chat_leaves_its_row_in_the_new_chat():
    assert [name for name, _ in ran(submit(state(), "/clear-chat"))] == ["clear_chat", "slash_ran"]


def test_a_pane_command_says_whether_it_showed_or_hid():
    made = state()
    assert ran(submit(made, "/python"))[0] == ("slash_ran", ["/python", "Python console: shown"])
    made.show_python = True
    assert ran(submit(made, "/python"))[0] == ("slash_ran", ["/python", "Python console: hidden"])


def test_anything_else_is_sent_to_the_agent():
    made = state()
    sent = submit(made, "who wins, Mac or Fox?")
    assert sent.handler.fn is State.send_chat.fn
    assert made.chat == []


def test_an_unknown_command_or_one_with_text_after_it_is_not_run():
    made = state()
    assert submit(made, "/nope") is None
    assert "isn't a command" in made.chat[-1].text
    assert "/clear-chat" in made.chat[-1].text
    assert submit(made, "/clear-chat but keep the last answer") is None
    assert "not run" in made.chat[-1].text


def test_the_palettes_plain_commands_have_slash_names():
    assert {"help", "keys", "debug", "variables", "python", "results", "close-tabs", "new-cell"} <= set(SLASH)
    # a widget is its kind: one with a tool takes text (for the inline AI), one without
    # takes none
    assert {f"/{widget.kind}" for widget in ADDABLE} <= {f"/{name}" for name in SLASH}
    assert SLASH["vods"].takes
    assert SLASH["vods"].slash_event == ("add_widget_ask", "vods")
    assert not SLASH["smashdb"].takes
    with pytest.raises(ValueError, match="needs a `slash_event`"):
        Command("x", "App", "X", "i", event=("toggle_help",), slash="x", takes="text")


def test_a_widgets_command_goes_to_its_slash_event_with_the_text_after_it():
    made = state()
    assert ran(submit(made, "/vods")) == [
        ("slash_ran", ["/vods", "Add: VODs"]),
        ("add_widget_ask", ["vods", ""]),
    ]
    assert ran(submit(made, "/vods mkleo vs sparg0 grand finals")) == [
        ("slash_ran", ["/vods", "mkleo vs sparg0 grand finals · Add: VODs"]),
        ("add_widget_ask", ["vods", "mkleo vs sparg0 grand finals"]),
    ]
    # a widget with no tool has nothing for the AI to fill
    assert submit(made, "/smashdb select 1") is None
    assert ran(submit(made, "/smashdb"))[1] == ("add_widget_ask", ["smashdb", ""])


def add_by_slash(made: State, kind: str, ask: str) -> None:
    async def run() -> None:
        async for _ in State.add_widget_ask.fn(made, kind, ask):
            pass

    asyncio.run(run())


def test_a_widget_command_shows_the_widget_in_the_chat():
    made = state()
    add_by_slash(made, "vods", "")
    held = made._session()
    assert isinstance(held.namespace["r1"], ToolRequest)
    # unfolded under the command, as a tool's result is; the panes stay as they were
    assert [(item.kind, item.name, item.open, item.view.kind) for item in made.chat] == [("ref", "r1", True, "tool")]
    assert not made.show_results
    # the + menu and the palette still add it as a tab only
    State.add_widget.fn(made, "vods")
    assert len(made.chat) == 1
    assert made.show_results


def test_a_widget_command_with_text_has_the_ais_inputs_proposed_in_the_chat(monkeypatch):
    async def fake_fill(session, form, shown, instruction, note=""):  # noqa: ARG001  # inline_fill.fill's shape
        asked.append((form.key, instruction))
        return Fill(inputs=form.texts({"player_1": "MkLeo", "player_2": "Sparg0"}), usage="$0.001")

    asked: list[tuple[str, str]] = []
    monkeypatch.setattr(state_module, "fill_inputs", fake_fill)
    made = state()
    add_by_slash(made, "vods", "mkleo vs sparg0")
    held = made._session()
    assert [instruction for _, instruction in asked] == ["mkleo vs sparg0"]
    # the form, not run: the AI's inputs are a proposal, on the widget shown in the chat
    assert isinstance(held.namespace["r1"], ToolRequest)
    assert held.ui["chat:r1"].proposed["player_1"] == "MkLeo"
    assert made.chat[-1].view.kind == "tool"


def test_clear_chat_forgets_the_conversation_and_keeps_the_variables():
    made = state(chat=[ChatItem(kind="user", text="hi"), ChatItem(kind="agent", text="hello")])
    session = made._session()
    session.ai_history, session.chat_tokens, session.ai_cost = ["a message"], 1200, 0.5
    session.namespace["r1"] = 1
    State.clear_chat.fn(made)
    assert made.chat == []
    assert (session.ai_history, session.chat_tokens) == ([], 0)
    assert (session.namespace["r1"], session.ai_cost) == (1, 0.5)
    # not while a turn is running
    made.busy = True
    made.chat = [ChatItem(kind="user", text="hi")]
    State.clear_chat.fn(made)
    assert made.chat[0].text == "hi"
    assert made.chat[-1].kind == "note"
